// Approach: The sheet asks whether the array is nondecreasing. The linked LeetCode variant also
//   allows one rotation, so both checks are shown.
#include <vector>
using namespace std;
bool isSorted(const vector<int>& values) {
    // A single decrease disproves ordinary nondecreasing order.
    for (int i = 1; i < (int)values.size(); ++i)
        if (values[i] < values[i - 1]) return false;
    return true;
}
bool isSortedAndRotated(const vector<int>& values) {
    int n = (int)values.size(), drops = 0;
    for (int i = 0; i < n; ++i)
        if (values[i] > values[(i + 1) % n]) ++drops;
    return drops <= 1; // includes the unrotated case
}

