// Approach: For the linked LeetCode task, XOR 0 through n with the array of n values; paired values
//   cancel. A separate helper covers the 1-through-n lesson variant.
#include <vector>
using namespace std;
int missingNumberZeroToN(const vector<int>& values) {
    int missing = (int)values.size();
    // Each present index/value pair cancels under XOR, leaving the gap.
    for (int i = 0; i < (int)values.size(); ++i)
        missing ^= i ^ values[i];
    return missing; // LeetCode: n values from 0..n
}
int missingNumberOneToN(const vector<int>& values, int n) {
    int missing = 0;
    for (int value = 1; value <= n; ++value) missing ^= value;
    for (int value : values) missing ^= value;
    return missing; // lesson variant: n-1 values from 1..n
}

