// Approach: XOR cancels each paired value, leaving the unpaired value.
#include <utility>
#include <vector>
using namespace std;
int singleNumber(const vector<int>& arr) {
    int answer = 0;
    // Every paired value cancels because x XOR x is zero.
    for (int value : arr) answer ^= value;  // x ^ x == 0, so every pair cancels out
    return answer;                          // only the unpaired value survives
}

s3-kadane-s-algorithm-maximum-subarray-s.code:
// Approach: Extend the running sum while it helps; the moment it goes negative it can only drag
//   future sums down, so reset to 0. Track the best sum seen at any point — even a single (negative)
//   element counts.
#include <algorithm>
#include <climits>
#include <vector>
using namespace std;
long long maxSubArraySum(vector<int>& arr) {
    long long best = LLONG_MIN, current = 0;
    // A negative running sum cannot improve any future subarray.
    for (int x : arr) {
        current += x;
        best = max(best, current);    // track the best sum seen anywhere
        if (current < 0) current = 0; // a negative running sum only hurts what follows
    }
    return best;
}

