s3-left-rotate-an-array-by-d-places.code:
// Approach: Three reversals rotate left by d in place. The linked LeetCode task rotates right, so a
//   right-rotation helper is also included.
#include <algorithm>
#include <vector>
using namespace std;
void rotateLeft(vector<int>& values, int d) {
    int n = (int)values.size();
    if (n == 0) return;
    d = (d % n + n) % n;
    reverse(values.begin(), values.begin() + d);
    reverse(values.begin() + d, values.end());
    reverse(values.begin(), values.end());
}
void rotateRight(vector<int>& values, int k) {
    int n = (int)values.size();
    if (n == 0) return;
    k = (k % n + n) % n;
    reverse(values.begin(), values.end());
    reverse(values.begin(), values.begin() + k);
    reverse(values.begin() + k, values.end());
}

