using namespace std;
void rotateLeftOne(vector<int>& values) {
    if (values.empty()) return;
    int first = values[0];
    // Shift each item into the previous slot after saving the first one.
    for (int i = 1; i < (int)values.size(); ++i)
        values[i - 1] = values[i];
    values.back() = first;
}
void rotateRightOne(vector<int>& values) {
    if (values.empty()) return;
    int last = values.back();
    for (int i = (int)values.size() - 1; i > 0; --i)
        values[i] = values[i - 1];
    values[0] = last;
}

