int removeDuplicates(vector<int>& arr) {
    int write = 0;
    // The write index is the length of the unique prefix built so far.
    for (int value : arr)
        if (write == 0 || value != arr[write - 1])  // keep it only if it differs from the last kept value
            arr[write++] = value;
    return write; // unique values occupy arr[0..write-1]
}

