// Approach: Track the largest and the strictly smaller runner-up. Use a found flag so INT_MIN remains
//   a valid answer.
#include <climits>
#include <vector>
using namespace std;
int secondLargest(const vector<int>& values) {
    int largest = INT_MIN, second = INT_MIN;
    bool hasLargest = false, hasSecond = false;
    // Keep two distinct values; duplicates of the maximum do not qualify.
    for (int value : values) {
        if (!hasLargest || value > largest) {
            if (hasLargest) { second = largest; hasSecond = true; }
            largest = value;
            hasLargest = true;
        } else if (value < largest && (!hasSecond || value > second)) {
            second = value;
            hasSecond = true;
        }
    }
    return hasSecond ? second : -1;
}

