// Approach: Merge the two sorted arrays with two pointers, adding a value only if it differs from the
//   last output.
#include <cstddef>
#include <vector>
using namespace std;
vector<int> sortedUnion(const vector<int>& a, const vector<int>& b) {
    vector<int> out;
    size_t i = 0, j = 0;
    // Merge the two sorted fronts and avoid repeating the last output.
    while (i < a.size() || j < b.size()) {
        int value;
        if (j == b.size() || (i < a.size() && a[i] <= b[j]))
            value = a[i++];
        else
            value = b[j++];
        if (out.empty() || out.back() != value) out.push_back(value);
    }
    return out;
}

s3-longest-subarray-with-given-sum-k-pos.code:
// Approach: For nonnegative values, expand the right end and shrink the left end while the sum
//   exceeds k.
#include <algorithm>
#include <vector>
using namespace std;
int longestSumKNonnegative(const vector<int>& a, long long k) {
    if (k < 0) return 0;
    long long sum = 0;
    int left = 0, best = 0;
    // Shrinking is safe only because all values are nonnegative.
    for (int right = 0; right < static_cast<int>(a.size()); ++right) {
        sum += a[right];
        while (left <= right && sum > k) sum -= a[left++];
        if (sum == k) best = max(best, right - left + 1);
    }
    return best;
}

