// Approach: Store the earliest index of each prefix sum; a previous prefix of current-k gives a sum-k
//   subarray.
#include <algorithm>
#include <unordered_map>
#include <vector>
using namespace std;
int longestSumKAnyIntegers(const vector<int>& a, long long k) {
    unordered_map<long long, int> first{{0, -1}};
    long long prefix = 0;
    int best = 0;
    // Keep the earliest occurrence of each prefix to maximize length.
    for (int i = 0; i < static_cast<int>(a.size()); ++i) {
        prefix += a[i];
        auto it = first.find(prefix - k);
        if (it != first.end()) best = max(best, i - it->second);
        first.emplace(prefix, i); // keep the earliest index
    }
    return best;
}

s3-2sum-problem.code:
// Approach: Before storing the current value, look up target-value among earlier values.
#include <climits>
#include <unordered_map>
#include <utility>
#include <vector>
using namespace std;
vector<int> twoSumIndices(const vector<int>& a, int target) {
    unordered_map<int, int> seen;
    // Check the complement before storing this element, so it cannot pair with itself.
    for (int i = 0; i < static_cast<int>(a.size()); ++i) {
        long long need = static_cast<long long>(target) - a[i];
        if (need >= INT_MIN && need <= INT_MAX) {
            auto it = seen.find(static_cast<int>(need));
            if (it != seen.end()) return {it->second, i};
        }
        seen.emplace(a[i], i);
    }
    return {}; // no pair
}

