// Approach: Dutch national flag: [0,low) are zeros, [low,mid) ones, and (high,n) twos.
#include <algorithm>
#include <vector>
using namespace std;
void sort012(vector<int>& a) {
    int low = 0, mid = 0, high = static_cast<int>(a.size()) - 1;
    // Only the middle region is unclassified; move each value to its correct side.
    while (mid <= high) {
        if (a[mid] == 0) swap(a[low++], a[mid++]);
        else if (a[mid] == 1) ++mid;
        else swap(a[mid], a[high--]); // inspect swapped-in value next
    }
}

