s3-print-subarray-with-maximum-subarray-.code:
// Approach: Kadane's algorithm tracks the best sum and its endpoints. The linked GFG page asks a
//   different adjacent-pair problem.
#include <climits>
#include <tuple>
#include <vector>
using namespace std;
tuple<long long, int, int> maxSumSubarray(const vector<int>& a) {
    if (a.empty()) return {0, -1, -1};
    long long running = 0, best = LLONG_MIN;
    int start = 0, bestLeft = 0, bestRight = 0;
    // When the running sum restarts, remember that new start index.
    for (int i = 0; i < static_cast<int>(a.size()); ++i) {
        if (running <= 0) { running = a[i]; start = i; }
        else running += a[i];
        if (running > best) {
            best = running;
            bestLeft = start;
            bestRight = i;
        }
    }
    return {best, bestLeft, bestRight};
}

