// Approach: Track the cheapest earlier price; selling today earns price-minimumSoFar.
#include <algorithm>
#include <climits>
#include <vector>
using namespace std;
int maxSingleTradeProfit(const vector<int>& prices) {
    int cheapest = INT_MAX, best = 0;
    // The minimum is from an earlier day, so buying always precedes selling.
    for (int price : prices) {
        cheapest = min(cheapest, price);
        best = max(best, price - cheapest);
    }
    return best;
}

