vector<int> alternateSigns(const vector<int>& a) {
    vector<int> positive, negative, out;
    // Separate signs first to preserve the order within each group.
    for (int x : a) (x >= 0 ? positive : negative).push_back(x);
    size_t p = 0, n = 0;
    while (p < positive.size() && n < negative.size()) {
        out.push_back(positive[p++]);
        out.push_back(negative[n++]);
