    while (n < negative.size()) out.push_back(negative[n++]);
    return out;
}

s3-next-permutation.code:
// Approach: Find the rightmost ascent, swap its smaller element with the next larger suffix value,
//   then reverse the suffix.
#include <algorithm>
#include <vector>
using namespace std;
void nextPermutationInPlace(vector<int>& a) {
    int n = static_cast<int>(a.size());
    if (n < 2) return;
    int pivot = n - 2;
    // The rightmost ascent is the position we can increase minimally.
    while (pivot >= 0 && a[pivot] >= a[pivot + 1]) --pivot;
    if (pivot >= 0) {
        int j = n - 1;
        while (a[j] <= a[pivot]) --j;
        swap(a[pivot], a[j]);
    }
    reverse(a.begin() + pivot + 1, a.end());
}

