// Approach: Scan from right to left; a value is a leader if it is at least as large as every value to
//   its right.
#include <algorithm>
#include <climits>
#include <vector>
using namespace std;
vector<int> leaders(const vector<int>& a) {
    vector<int> out;
    int greatestRight = INT_MIN;
    // Maintain the greatest value seen to the right.
    for (int i = static_cast<int>(a.size()) - 1; i >= 0; --i) {
        if (a[i] >= greatestRight) out.push_back(a[i]);
        greatestRight = max(greatestRight, a[i]);
    }
    reverse(out.begin(), out.end());
    return out;
}

