// Approach: Start counting only at numbers whose predecessor is absent, then walk each consecutive
//   run once.
#include <algorithm>
#include <climits>
#include <unordered_set>
#include <vector>
using namespace std;
int longestConsecutive(const vector<int>& a) {
    unordered_set<int> values(a.begin(), a.end());
    int best = 0;
    // Only count from a value whose predecessor is absent.
    for (int x : values) {
        if (x != INT_MIN && values.count(x - 1)) continue;
        int length = 1, current = x;
        while (current != INT_MAX && values.count(current + 1)) {
            ++current;
            ++length;
        }
        best = max(best, length);
    }
    return best;
}

s3-set-matrix-zeros.code:
// Approach: Use the first row and column as markers, remembering separately whether the first column
//   originally had a zero.
#include <vector>
using namespace std;
void setMatrixZeroes(vector<vector<int>>& a) {
    if (a.empty() || a[0].empty()) return;
    int rows = a.size(), cols = a[0].size();
    bool firstColZero = false;
    // The first row and column hold markers for rows and columns to clear.
    for (int r = 0; r < rows; ++r) {
        if (a[r][0] == 0) firstColZero = true;
        for (int c = 1; c < cols; ++c)
            if (a[r][c] == 0) a[r][0] = a[0][c] = 0;
    }
    for (int r = rows - 1; r >= 0; --r) {
        for (int c = cols - 1; c >= 1; --c)
            if (a[r][0] == 0 || a[0][c] == 0) a[r][c] = 0;
        if (firstColZero) a[r][0] = 0;
    }
}

