void rotateClockwise90(vector<vector<int>>& a) {
    int n = a.size();
    // Transpose first; reversing each row then turns it clockwise.
    for (int r = 0; r < n; ++r)
        for (int c = r + 1; c < n; ++c)
            swap(a[r][c], a[c][r]);
    for (auto& row : a) reverse(row.begin(), row.end());
}

s3-print-the-matrix-in-spiral-manner.code:
// Approach: Maintain top, bottom, left, and right boundaries; traverse one edge, then shrink its
//   boundary.
#include <vector>
using namespace std;
vector<int> spiralOrder(const vector<vector<int>>& a) {
    if (a.empty() || a[0].empty()) return {};
    int top = 0, bottom = static_cast<int>(a.size()) - 1;
    int left = 0, right = static_cast<int>(a[0].size()) - 1;
    vector<int> out;
    // After walking an edge, move that boundary inward.
    while (top <= bottom && left <= right) {
        for (int c = left; c <= right; ++c) out.push_back(a[top][c]);
        ++top;
        for (int r = top; r <= bottom; ++r) out.push_back(a[r][right]);
        --right;
        if (top <= bottom) {
            for (int c = right; c >= left; --c) out.push_back(a[bottom][c]);
            --bottom;
        }
        if (left <= right) {
            for (int r = bottom; r >= top; --r) out.push_back(a[r][left]);
            ++left;
        }
    }
    return out;
}

