long long countSubarraysSumK(const vector<int>& a, long long k) {
    unordered_map<long long, long long> seen{{0, 1}};
    long long prefix = 0, answer = 0;
    // Every earlier prefix equal to current minus k forms a valid subarray.
    for (int x : a) {
        prefix += x;
        auto it = seen.find(prefix - k);
        if (it != seen.end()) answer += it->second;
        ++seen[prefix];
    }
    return answer;
}

s3-pascal-s-triangle.code:
// Approach: Each inner cell is the sum of the two cells directly above it; edge cells are one.
#include <vector>
using namespace std;
vector<vector<long long>> pascalTriangle(int rows) {
    vector<vector<long long>> result;
    // Boundary entries stay one; inner entries add the two parents.
    for (int r = 0; r < rows; ++r) {
        result.push_back(vector<long long>(r + 1, 1));
        for (int c = 1; c < r; ++c)
            result[r][c] = result[r - 1][c - 1] + result[r - 1][c];
    }
    return result;
}

s3-majority-element-n-3-times.code:
// Approach: At most two values can occur more than n/3 times. Cancel triples of distinct values, then
//   verify candidates.
#include <algorithm>
#include <vector>
using namespace std;
vector<int> majorityOverThird(const vector<int>& a) {
    int first = 0, second = 0, countFirst = 0, countSecond = 0;
    // Three distinct values can cancel together, leaving at most two candidates.
    for (int x : a) {
        if (countFirst && x == first) ++countFirst;
        else if (countSecond && x == second) ++countSecond;
        else if (countFirst == 0) { first = x; countFirst = 1; }
        else if (countSecond == 0) { second = x; countSecond = 1; }
        else { --countFirst; --countSecond; }
    }
    countFirst = countSecond = 0;
    for (int x : a) {
        if (x == first) ++countFirst;
        else if (x == second) ++countSecond;
    }
    vector<int> out;
    if (countFirst > static_cast<int>(a.size()) / 3) out.push_back(first);
    if (countSecond > static_cast<int>(a.size()) / 3) out.push_back(second);
    sort(out.begin(), out.end());
    return out;
}

s3-3-sum-problem.code:
// Approach: Sort; fix one value, then sweep the remaining range with two pointers, skipping
//   duplicates.
#include <algorithm>
#include <vector>
using namespace std;
vector<vector<int>> threeSum(vector<int> a) {
    sort(a.begin(), a.end());
    vector<vector<int>> out;
    int n = a.size();
    // Fix one value, then find the remaining pair with two pointers.
    for (int i = 0; i + 2 < n; ++i) {
        if (i && a[i] == a[i - 1]) continue;
        int left = i + 1, right = n - 1;
        while (left < right) {
            long long sum = static_cast<long long>(a[i]) + a[left] + a[right];
            if (sum < 0) ++left;
            else if (sum > 0) --right;
            else {
                out.push_back({a[i], a[left], a[right]});
                int lv = a[left], rv = a[right];
                while (left < right && a[left] == lv) ++left;
                while (left < right && a[right] == rv) --right;
            }
        }
    }
    return out;
}

s3-4-sum-problem.code:
// Approach: Sort, fix two values, then use two pointers for the remaining pair; skip duplicates at
//   every level.
#include <algorithm>
#include <vector>
using namespace std;
vector<vector<int>> fourSum(vector<int> a, long long target) {
    sort(a.begin(), a.end());
    vector<vector<int>> out;
    int n = a.size();
    // Fix two values, then find the remaining pair with two pointers.
    for (int i = 0; i + 3 < n; ++i) {
        if (i && a[i] == a[i - 1]) continue;
        for (int j = i + 1; j + 2 < n; ++j) {
            if (j > i + 1 && a[j] == a[j - 1]) continue;
            int left = j + 1, right = n - 1;
            while (left < right) {
                long long sum = static_cast<long long>(a[i]) + a[j] + a[left] + a[right];
                if (sum < target) ++left;
                else if (sum > target) --right;
                else {
                    out.push_back({a[i], a[j], a[left], a[right]});
                    int lv = a[left], rv = a[right];
                    while (left < right && a[left] == lv) ++left;
                    while (left < right && a[right] == rv) --right;
                }
            }
        }
    }
    return out;
}

