// Approach: Sort intervals by start; extend the last merged interval while the next one overlaps.
#include <algorithm>
#include <vector>
using namespace std;
vector<vector<int>> mergeIntervals(vector<vector<int>> intervals) {
    sort(intervals.begin(), intervals.end());
    vector<vector<int>> out;
    // Sorted starts let us compare only with the last merged interval.
    for (const auto& interval : intervals) {
        if (out.empty() || interval[0] > out.back()[1])
            out.push_back(interval);
        else
            out.back()[1] = max(out.back()[1], interval[1]);
    }
    return out;
}

s3-merge-two-sorted-arrays-without-extra.code:
// Approach: Use shrinking gaps for two full arrays; fill from the back when the first has spare slots.
#include <algorithm>
#include <vector>
using namespace std;
int& elementAt(vector<int>& a, vector<int>& b, int index) {
    if (index < (int)a.size()) return a[index];
    return b[index - (int)a.size()];
}
void mergeSortedWithoutExtra(vector<int>& a, vector<int>& b) {
    int total = (int)a.size() + (int)b.size();
    int gap = (total + 1) / 2;
    while (gap > 0) {
        // Treat both arrays as one sequence without making a third array.
        for (int i = 0; i + gap < total; ++i) {
            if (elementAt(a, b, i) > elementAt(a, b, i + gap)) {
                swap(elementAt(a, b, i), elementAt(a, b, i + gap));
            }
        }
        if (gap == 1) break;
        gap = (gap + 1) / 2;
    }
}
void mergeIntoFirst(vector<int>& a, int m, const vector<int>& b) {
    int i = m - 1;
    int j = (int)b.size() - 1;
    int write = m + j;
    // Put the larger value at the end so unread values are not overwritten.
    while (j >= 0) {
        if (i >= 0 && a[i] > b[j]) a[write--] = a[i--];
        else a[write--] = b[j--];
    }
}

s3-find-the-repeating-and-missing-number.code:
// Approach: Use each value as an index and negate the value there; an already-negative slot reveals
//   the duplicate. The positive slot reveals the missing value.
#include <cstdlib>
#include <utility>
#include <vector>
using namespace std;
pair<int, int> repeatingAndMissing(vector<int>& a) {
    int duplicate = -1, missing = -1;
    // Negating a slot marks its value as seen without extra storage.
    for (int value : a) {
        int index = abs(value) - 1;
        if (a[index] < 0) duplicate = index + 1;
        else a[index] = -a[index];
    }
    for (int i = 0; i < static_cast<int>(a.size()); ++i) {
        if (a[i] > 0) missing = i + 1;
        a[i] = abs(a[i]); // restore caller's array
    }
    return {duplicate, missing};
}

s3-count-inversions.code:
// Approach: Merge sort counts pairs inside each half and pairs crossing the middle.
#include <vector>
using namespace std;
long long countInversionsInRange(vector<int>& a, vector<int>& temp, int left, int right) {
    if (right - left <= 1) return 0;
    int mid = left + (right - left) / 2;
    long long count = countInversionsInRange(a, temp, left, mid);
    count += countInversionsInRange(a, temp, mid, right);
    int i = left, j = mid, write = left;
    while (i < mid && j < right) {
        if (a[i] <= a[j]) {
            temp[write++] = a[i++];
        } else {
            // a[i] through a[mid-1] are all greater than a[j].
            count += mid - i;
            temp[write++] = a[j++];
        }
    }
    while (i < mid) temp[write++] = a[i++];
    while (j < right) temp[write++] = a[j++];
    for (int k = left; k < right; ++k) a[k] = temp[k];
    return count;
}
long long countInversions(vector<int> a) {
    vector<int> temp(a.size());
    return countInversionsInRange(a, temp, 0, (int)a.size());
}

s3-reverse-pairs.code:
// Approach: Sort both halves, count cross-half reverse pairs, then merge the halves.
#include <vector>
using namespace std;
long long countReversePairsInRange(vector<int>& a, vector<int>& temp, int left, int right) {
    if (right - left <= 1) return 0;
    int mid = left + (right - left) / 2;
    long long count = countReversePairsInRange(a, temp, left, mid);
    count += countReversePairsInRange(a, temp, mid, right);
    int j = mid;
    for (int i = left; i < mid; ++i) {
        // Each half is sorted, so j never needs to move backward.
        while (j < right && (long long)a[i] > 2LL * a[j]) ++j;
        count += j - mid;
    }
    int i = left;
    j = mid;
    int write = left;
    while (i < mid && j < right) {
        if (a[i] <= a[j]) temp[write++] = a[i++];
        else temp[write++] = a[j++];
    }
    while (i < mid) temp[write++] = a[i++];
    while (j < right) temp[write++] = a[j++];
    for (int k = left; k < right; ++k) a[k] = temp[k];
    return count;
}
long long countReversePairs(vector<int> a) {
    vector<int> temp(a.size());
    return countReversePairsInRange(a, temp, 0, (int)a.size());
}

