// Approach: Keep both products because a negative number can turn the smallest into the largest.
#include <algorithm>
#include <vector>
using namespace std;
long long maxProductSubarray(const vector<int>& a) {
    // The linked problem guarantees at least one element.
    long long highest = a[0], lowest = a[0], best = a[0];
    for (int i = 1; i < (int)a.size(); ++i) {
        long long value = a[i];
        if (value < 0) swap(highest, lowest);
        highest = max(value, highest * value);
        lowest = min(value, lowest * value);
        best = max(best, highest);
    }
    return best;
}
